import {addLargeDeposits,classifyDeposits} from './engine.js';
import {serializeCampaign,restoreCampaign,clearRequestedBunker2,clearRequestedBunkers234,resetUnexploredBunkers} from './campaign.js';
const KEY='last-city-v1';
function database(){return new Promise((resolve,reject)=>{let q=indexedDB.open('last-city',1);q.onupgradeneeded=()=>q.result.createObjectStore('world');q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error);});}
export async function saveWorld(s){let text=serializeCampaign(s);let db=await database();try{await new Promise((resolve,reject)=>{let tx=db.transaction('world','readwrite');tx.objectStore('world').put(text,KEY);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});}finally{db.close();}}
export async function loadWorld(){let db=await database(),text;try{text=await new Promise((resolve,reject)=>{let q=db.transaction('world').objectStore('world').get(KEY);q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error);});}finally{db.close();}return text?prepareLoadedCampaign(restoreCampaign(text)):null;}
export async function prepareLoadedCampaign(c){if(!c.unexploredResetV18){let db=await database();try{await new Promise((resolve,reject)=>{let tx=db.transaction('world','readwrite');tx.objectStore('world').put(serializeCampaign({...c,unexploredResetV18:true,bunkers234CleanupV17:true,bunker2CleanupV15:true}),'before-unexplored-reset-v18');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});}finally{db.close();}resetUnexploredBunkers(c);}if(!c.bunkers234CleanupV17){let db=await database();try{await new Promise((resolve,reject)=>{let tx=db.transaction('world','readwrite');tx.objectStore('world').put(serializeCampaign({...c,bunkers234CleanupV17:true,bunker2CleanupV15:true}),'before-bunkers234-cleanup-v17');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});}finally{db.close();}clearRequestedBunkers234(c);}if(!c.bunker2CleanupV15){let db=await database();try{await new Promise((resolve,reject)=>{let tx=db.transaction('world','readwrite');tx.objectStore('world').put(serializeCampaign({...c,bunker2CleanupV15:true}),'before-bunker2-cleanup-v15');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});}finally{db.close();}clearRequestedBunker2(c);}for(let b of c.bunkers){addLargeDeposits(b.world);classifyDeposits(b.world);}return c;}
export async function cleanupBackupText(){let db=await database();try{return await new Promise((resolve,reject)=>{let q=db.transaction('world').objectStore('world').get('before-unexplored-reset-v18');q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error);});}finally{db.close();}}
